  organizationDialogTitle:'\u5b8c\u5584\u673a\u6784\u4fe1\u606f',organizationDialogText:'\u5fae\u4fe1\u5df2\u6388\u6743\u3002\u8bf7\u5148\u5efa\u7acb\u4f60\u7684\u673a\u6784\uff0c\u518d\u9009\u62e9\u8d5b\u4e8b\u6216\u9752\u8bad\u4e1a\u52a1\u3002',organizationName:'\u673a\u6784\u540d\u79f0',organizationNameHint:'\u4f8b\u5982\uff1a\u90d1\u5dde\u8d5b\u5c0f\u8702\u8db3\u7403\u4ff1\u4e50\u90e8',organizationType:'\u673a\u6784\u7c7b\u578b',organizationTypeHint:'\u8bf7\u9009\u62e9\u673a\u6784\u7c7b\u578b',organizationProvince:'\u673a\u6784\u6240\u5728\u7701\u4efd',organizationCity:'\u673a\u6784\u6240\u5728\u57ce\u5e02',organizationCityHint:'\u8bf7\u5148\u9009\u62e9\u7701\u4efd',createOrganization:'\u521b\u5efa\u673a\u6784\u5e76\u7ee7\u7eed',
  trainingReady:'\u9752\u8bad\u80fd\u529b\u5df2\u5f00\u901a',trainingLocked:'\u9752\u8bad\u80fd\u529b\u5c1a\u672a\u5f00\u901a',trainingPanel:'\u9752\u8bad\u662f\u72ec\u7acb\u670d\u52a1\u80fd\u529b\uff0c\u5f00\u901a\u72b6\u6001\u7531\u540e\u53f0\u8d44\u683c\u51b3\u5b9a\uff0c\u9875\u9762\u4e0d\u4f1a\u7ed5\u8fc7\u8d44\u683c\u6821\u9a8c\u3002',orgName:'\u673a\u6784\u540d\u79f0',orgHint:'\u4f8b\u5982\uff1a\u8d5b\u5c0f\u8702\u9752\u8bad\u4e2d\u5fc3',createTraining:'\u521b\u5efa\u9752\u8bad\u5de5\u4f5c\u7a7a\u95f4',status:'\u5f53\u524d\u72b6\u6001\uff1a',trainingLockedText:'\u5982\u679c\u4f60\u5df2\u5b8c\u6210\u5f00\u901a\uff0c\u8bf7\u5237\u65b0\uff1b\u8fd8\u6ca1\u6709\u5f00\u901a\u5219\u53ef\u4ee5\u7559\u4e0b\u54a8\u8be2\u7533\u8bf7\u3002',consult:'\u54a8\u8be2\u9752\u8bad\u5f00\u901a',consulted:'\u5df2\u63d0\u4ea4\u54a8\u8be2'
