const organizationDialogText = computed(() => canCreateOrganizationFromTeams.value ? '你已是球队负责人。请先明确建立独立机构，再勾选要接入的球队；机构名称不会从球队名自动生成。' : t.organizationDialogText)
const organizationSubmitText = computed(() => canCreateOrganizationFromTeams.value ? '创建机构并接入球队' : t.createOrganization)
