const accountInitial=computed(()=>accountDisplayName.value.charAt(0)||'\u8702')
const organizationDisplayName=computed(()=>state.value?.organization?.name||state.value?.organization?.organizationName||storedAccount.organizationName||'\u5c1a\u672a\u5efa\u7acb\u673a\u6784')
