async function loadState(){loading.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'state'});if(!result?.success)throw new Error(result?.message||result?.error||'state failed');state.value=result;selectedTeamIds.value=[];trainingReady.value=Boolean(result.training?.hasBackendProvision&&['active','enabled','paid','trial'].includes(String(result.training?.status||'')));const organization=result.organization;if(organization?.id||organization?._id){persistOrganization(organization);organizationDialogVisible.value=false;const capabilities=Array.isArray(organization.capabilities)?organization.capabilities:[];if(capabilities.includes('event')||capabilities.includes('education'))router.replace('/tournament-space')}else{organizationDialogVisible.value=Boolean(!result.hasBusinessRelation||result.canCreateOrganizationFromTeams)}}catch(error){organizationDialogVisible.value=false;ElMessage.error(error.message||'state failed')}finally{loading.value=false}}
