async function saveProfile(){if(profileSubmitting.value)return;if(!profileForm.nickname)return ElMessage.warning('\u8bf7\u8f93\u5165\u8d26\u53f7\u663e\u793a\u540d\u79f0');profileSubmitting.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'updateProfile',nickname:profileForm.nickname});if(!result?.success)throw new Error(result?.message||result?.error||'save failed');accountInfo.userName=result.user?.nickname||profileForm.nickname;const user=JSON.parse(localStorage.getItem('userInfo')||'{}');localStorage.setItem('userInfo',JSON.stringify({...user,userName:accountInfo.userName,nickname:accountInfo.userName}));profileDialogVisible.value=false;ElMessage.success('\u4e2a\u4eba\u8d44\u6599\u5df2\u66f4\u65b0')}catch(error){ElMessage.error(error.message||'save failed')}finally{profileSubmitting.value=false}}
async function saveOrganization(){if(organizationEditSubmitting.value)return;if(organizationEditForm.name.length<2||!organizationEditForm.organizationType||!organizationEditForm.provinceCode||!organizationEditForm.city)return ElMessage.warning('\u8bf7\u5b8c\u6574\u586b\u5199\u673a\u6784\u8d44\u6599');organizationEditSubmitting.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'updateOrganization',name:organizationEditForm.name,organizationType:organizationEditForm.organizationType,provinceCode:organizationEditForm.provinceCode,province:provinceName(organizationEditForm.provinceCode),city:organizationEditForm.city});if(!result?.success)throw new Error(result?.message||result?.error||'save failed');state.value={...(state.value||{}),organization:result.organization};persistOrganization(result.organization);organizationEditDialogVisible.value=false;ElMessage.success('\u673a\u6784\u8d44\u6599\u5df2\u66f4\u65b0')}catch(error){ElMessage.error(error.message||'save failed')}finally{organizationEditSubmitting.value=false}}
async function createOrganization(){if(organizationSubmitting.value)return;if(organizationForm.name.length<2||!organizationForm.organizationType||!organizationForm.provinceCode||!organizationForm.city)return ElMessage.warning('\u8bf7\u5b8c\u6574\u586b\u5199\u673a\u6784\u540d\u79f0\u3001\u7c7b\u578b\u548c\u6240\u5728\u7701\u5e02');if(canCreateOrganizationFromTeams.value&&!selectedTeamIds.value.length)return ElMessage.warning('\u8bf7\u81f3\u5c11\u52fe\u9009\u4e00\u652f\u8981\u63a5\u5165\u673a\u6784\u7684\u7403\u961f');organizationSubmitting.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'createOrganization',name:organizationForm.name,organizationType:organizationForm.organizationType,provinceCode:organizationForm.provinceCode,province:provinceName(organizationForm.provinceCode),city:organizationForm.city,attachTeamIds:selectedTeamIds.value.slice()});if(!result?.success)throw new Error(result?.message||result?.error||'create failed');state.value={...(state.value||{}),organization:result.organization,hasBusinessRelation:true,requiresOnboarding:true,manageableTeams:[]};persistOrganization(result.organization);organizationDialogVisible.value=false;ElMessage.success(result.attachedTeams?.length?'\u673a\u6784\u5df2\u521b\u5efa\uff0c\u5df2\u63a5\u5165\u9009\u4e2d\u7403\u961f':'\u673a\u6784\u5df2\u521b\u5efa\uff0c\u8bf7\u7ee7\u7eed\u9009\u62e9\u4e1a\u52a1')}catch(error){ElMessage.error(error.message||'create failed')}finally{organizationSubmitting.value=false}}
async function choose(value){scene.value=value;try{await callFunction('onboardingWorkspace',{action:'saveScene',scene:value})}catch{}}
async function createEvent(){if(submitting.value)return;if(eventForm.name.length<2||!eventForm.provinceCode||!eventForm.city)return ElMessage.warning('\u8bf7\u586b\u5199\u8d5b\u4e8b\u540d\u79f0\u5e76\u9009\u62e9\u4e3e\u529e\u7701\u5e02');submitting.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'createEventSpace',name:eventForm.name,provinceCode:eventForm.provinceCode,province:provinceName(eventForm.provinceCode),city:eventForm.city});if(!result?.success)throw new Error(result?.message||result?.error||'create failed');persistOrganization(result.organization||{id:result.organizationId,name:eventForm.name+'\u4e3b\u529e\u65b9'});router.replace(result.tournament?.id?'/tournaments/'+result.tournament.id:'/tournament-space')}catch(error){ElMessage.error(error.message||'create failed')}finally{submitting.value=false}}
async function createTraining(){if(submitting.value)return;submitting.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'createTrainingWorkspace'});if(!result?.success)throw new Error(result?.message||result?.error||'create failed');persistOrganization(result.organization);ElMessage.success('\u9752\u8bad\u5de5\u4f5c\u7a7a\u95f4\u5df2\u521b\u5efa');router.replace('/tournament-space')}catch(error){ElMessage.error(error.message||'create failed')}finally{submitting.value=false}}
async function consult(){if(submitting.value||consulted.value)return;submitting.value=true;try{const result=await callFunction('onboardingWorkspace',{action:'createTrainingConsultation'});if(!result?.success)throw new Error(result?.message||result?.error||'consult failed');consulted.value=true;ElMessage.success('\u54a8\u8be2\u7533\u8bf7\u5df2\u63d0\u4ea4')}catch(error){ElMessage.error(error.message||'consult failed')}finally{submitting.value=false}}
function persistOrganization(organization){if(!organization?.id&&!organization?._id)return;const id=organization.id||organization._id,name=organization.name||organization.organizationName||'';let user={};try{user=JSON.parse(localStorage.getItem('userInfo')||'{}')}catch{}localStorage.setItem('userInfo',JSON.stringify({...user,orgId:id,organizationId:id,organizationName:name}));localStorage.setItem('currentOrganization',JSON.stringify({...organization,id,name}))}
async function signOut(){await logout();router.replace('/login')}
onMounted(loadState)
</script>
